    lastAt = Math.max(lastAt, o.b);
    W.at(T0 + o.a, () => { W.log('SERVER', 'outage (' + o.mode + ') for ' + Math.round((o.b - o.a) / 1000) + ' s'); for (const P of W.players) W.mark(P, 'outage', { a: T0 + o.a, b: T0 + o.b }); }, null);
