      if (g.oppRatingUsed !== pr.H.rating) add('I10', 'guest-used-wrong-opp-rating', 'medium', pr.G.label, rg.t, 'guest recorded opp rating ' + g.oppRatingUsed + ', host rating is ' + pr.H.rating);
